mapper.select:
SELECT f.id, f.target_type AS targetType, f.target_id AS targetId, f.create_time AS createTime, CASE f.target_type WHEN 1 THEN g.name WHEN 2 THEN c.title WHEN 3 THEN a.title END AS title, CASE f.target_type WHEN 1 THEN g.subtitle WHEN 2 THEN c.subtitle WHEN 3 THEN a.summary END AS subtitle, CASE f.target_type WHEN 1 THEN g.cover WHEN 2 THEN c.cover WHEN 3 THEN a.cover END AS cover, CASE f.target_type WHEN 1 THEN g.price WHEN 2 THEN c.price ELSE NULL END AS price, CASE WHEN f.target_type = 1 THEN (g.id IS NOT NULL AND g.deleted = 0 AND g.status = 1) WHEN f.target_type = 2 THEN (c.id IS NOT NULL AND c.deleted = 0 AND c.audit_status = 1) WHEN f.target_type = 3 THEN (a.id IS NOT NULL AND a.deleted = 0 AND a.status = 1) ELSE 0 END AS targetAvailable FROM favorite f LEFT JOIN goods g ON f.target_type = 1 AND g.id = f.target_id LEFT JOIN course c ON f.target_type = 2 AND c.id = f.target_id LEFT JOIN article a ON f.target_type = 3 AND a.id = f.target_id WHERE f.deleted = 0 AND f.user_id = #{userId}
AND f.target_type = #{targetType}
ORDER BY f.id DESC
